data class RobotConfig(val teamName: String?)

fun getTeamNameUpperCase(config: RobotConfig?): String {
    return config?.teamName?.uppercase() ?: "NO TEAM"
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testWithTeamName() {
        Assert.assertEquals("TRIBOTS", getTeamNameUpperCase(RobotConfig("Tribots")))
    }

    @Test
    fun testWithNullTeamName() {
        Assert.assertEquals("NO TEAM", getTeamNameUpperCase(RobotConfig(null)))
    }

    @Test
    fun testWithNullConfig() {
        Assert.assertEquals("NO TEAM", getTeamNameUpperCase(null))
    }

    @Test
    fun testWithAnotherTeam() {
        Assert.assertEquals("ROBOWARRIORS", getTeamNameUpperCase(RobotConfig("RoboWarriors")))
    }
}
